import heapq


def farthest_rooftop(heights: list[int], bricks: int, ladders: int) -> int:
    ladder_climbs = []                       # min-heap: the climbs the ladders cover so far
    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb <= 0:
            continue                         # going down or level is free
        heapq.heappush(ladder_climbs, climb)
        if len(ladder_climbs) > ladders:
            bricks -= heapq.heappop(ladder_climbs)   # the smallest climb is paid in bricks
            if bricks < 0:
                return i
    return len(heights) - 1

perf.naive:
def farthest_rooftop(heights: list[int], bricks: int, ladders: int) -> int:
    climbs = []
    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb > 0:
            climbs.append(climb)
            climbs.sort(reverse=True)            # re-plan: ladders on the largest climbs
            if sum(climbs[ladders:]) > bricks:
                return i
    return len(heights) - 1
